//! QMK keycode names, as `.svil` files and Keybard write them.
//!
//! Names come from Keybard's keycode catalog numbered as QMK keycode version
//! [`KEYCODE_VERSION`](super::KEYCODE_VERSION) (`qmk_names.rs`, generated by
//! `tools/dump_keycodes.mjs`). The board's own keycodes (`customKeycodes` in its
//! definition) take the `QK_USER` range in order and are named after it.

use super::qmk_names::{CODE_TO_NAME, NAME_TO_CODE, RANGES};

/// First code of QMK's `QK_USER` range; custom keycode `n` is `QK_USER + n`.
pub const QK_USER: u16 = 0x7E40;
pub const QK_USER_MAX: u16 = 0x7FFF;
pub const QK_USER_COUNT: usize = (QK_USER_MAX - QK_USER) as usize + 1;

/// A keyboard-specific keycode from the definition's `customKeycodes`.
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct CustomKeycode {
    pub name: String,
    pub title: String,
    pub short_name: String,
}

impl CustomKeycode {
    /// The label to show on a key.
    pub fn label(&self) -> &str {
        if !self.short_name.is_empty() {
            &self.short_name
        } else if !self.title.is_empty() {
            &self.title
        } else {
            &self.name
        }
    }

    /// Read `customKeycodes` from a keyboard definition.
    #[cfg(feature = "std")]
    pub fn from_definition(def: &serde_json::Value) -> Vec<CustomKeycode> {
        let s = |v: &serde_json::Value, k: &str| v.get(k).and_then(|x| x.as_str()).unwrap_or("").to_string();
        def.get("customKeycodes")
            .and_then(|v| v.as_array())
            .map(|arr| {
                arr.iter()
                    .map(|v| CustomKeycode { name: s(v, "name"), title: s(v, "title"), short_name: s(v, "shortName") })
                    .collect()
            })
            .unwrap_or_default()
    }
}

/// Turns keycodes into names and back for one keyboard.
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct KeycodeNames {
    custom: Vec<CustomKeycode>,
}

fn table_name(code: u16) -> Option<&'static str> {
    CODE_TO_NAME
        .binary_search_by_key(&code, |&(c, _)| c)
        .ok()
        .map(|i| CODE_TO_NAME[i].1)
}

fn table_code(name: &str) -> Option<u16> {
    NAME_TO_CODE
        .binary_search_by(|&(n, _)| n.cmp(name))
        .ok()
        .map(|i| NAME_TO_CODE[i].1)
}

fn hex(code: u16) -> String {
    format!("0x{code:04x}")
}

/// `name(kc)` templates: the part before `(kc)`.
fn template_prefix(name: &str) -> Option<&str> {
    let prefix = name.strip_suffix("(kc)")?;
    if !prefix.is_empty() && prefix.chars().all(|c| c.is_ascii_alphanumeric() || c == '_') {
        Some(prefix)
    } else {
        None
    }
}

fn is_word(s: &str) -> bool {
    !s.is_empty() && s.chars().all(|c| c.is_ascii_alphanumeric() || c == '_')
}

fn layer_mod_range() -> (u16, u16) {
    RANGES
        .iter()
        .find(|(_, _, name)| *name == "QK_LAYER_MOD")
        .map(|&(first, size, _)| (first, first + size))
        .unwrap_or((0x5000, 0x51FF))
}

const MOD_NAMES: [&str; 4] = ["CTL", "SFT", "ALT", "GUI"];

/// `LM(1, MOD_LCTL|MOD_LSFT)` for a code in the Layer-Mod range.
fn layer_mod_string(code: u16) -> Option<String> {
    let (first, last) = layer_mod_range();
    if code <= first || code > last {
        return None;
    }
    let rel = code - first;
    let layer = (rel >> 5) & 0xF;
    let mods = rel & 0x1F;
    if mods & 0x10 != 0 && mods & 0xF == 0 {
        return None;
    }
    let side = if mods & 0x10 != 0 { "R" } else { "L" };
    let parts: Vec<String> = MOD_NAMES
        .iter()
        .enumerate()
        .filter(|(i, _)| mods & (1 << i) != 0)
        .map(|(_, n)| format!("MOD_{side}{n}"))
        .collect();
    let mods_str = if parts.is_empty() { "0".to_string() } else { parts.join("|") };
    Some(format!("LM({layer}, {mods_str})"))
}

fn parse_layer_mod(text: &str) -> Option<u16> {
    let inner = text.strip_prefix("LM(")?.strip_suffix(')')?;
    let (layer, mods) = inner.split_once(',')?;
    let layer: u16 = layer.trim().parse().ok()?;
    if layer > 0xF {
        return None;
    }
    let mut bits = 0u16;
    let mut side: Option<char> = None;
    for part in mods.split('|').map(str::trim) {
        if part == "0" {
            continue;
        }
        let rest = part.strip_prefix("MOD_")?;
        let mut chars = rest.chars();
        let s = chars.next()?;
        if s != 'L' && s != 'R' {
            return None;
        }
        let idx = MOD_NAMES.iter().position(|n| *n == chars.as_str())?;
        if side.is_some_and(|prev| prev != s) {
            return None;
        }
        side = Some(s);
        bits |= 1 << idx;
    }
    if side == Some('R') {
        bits |= 0x10;
    }
    let (first, _) = layer_mod_range();
    Some(first | (layer << 5) | bits)
}

fn qk_user_index(name: &str) -> Option<usize> {
    if name == "QK_USER" {
        return Some(0);
    }
    let n = name.strip_prefix("QK_USER_")?;
    if n.is_empty() || n.len() > 3 || !n.chars().all(|c| c.is_ascii_digit()) || (n.len() > 1 && n.starts_with('0')) {
        return None;
    }
    let n: usize = n.parse().ok()?;
    (n < QK_USER_COUNT).then_some(n)
}

impl KeycodeNames {
    pub fn new(custom: Vec<CustomKeycode>) -> Self {
        Self { custom }
    }

    pub fn custom_keycodes(&self) -> &[CustomKeycode] {
        &self.custom
    }

    /// The custom keycode a code stands for, if any.
    pub fn custom_for(&self, code: u16) -> Option<&CustomKeycode> {
        if code < QK_USER {
            return None;
        }
        self.custom.get((code - QK_USER) as usize).filter(|c| !c.name.is_empty())
    }

    fn name_of(&self, code: u16) -> Option<String> {
        if let Some(c) = self.custom_for(code) {
            return Some(c.name.clone());
        }
        table_name(code).map(str::to_string)
    }

    fn code_of(&self, name: &str) -> Option<u16> {
        if let Some(i) = self.custom.iter().position(|c| c.name == name) {
            if i < QK_USER_COUNT {
                return Some(QK_USER + i as u16);
            }
        }
        table_code(name)
    }

    /// The name of a keycode: `KC_A`, `LCTL(KC_A)`, `LT1(KC_SPC)`, `MO(2)`,
    /// `LM(1, MOD_LSFT)`, a custom name, or `0x1234` for one without a name.
    pub fn stringify(&self, code: u16) -> String {
        let modmask = code & 0xFF00;
        let keyid = code & 0x00FF;
        let mask_name = self.name_of(modmask);
        if modmask != 0 && keyid == 0 {
            if let Some(m) = mask_name.as_deref() {
                if template_prefix(m).is_some() {
                    if m == "ALL_T(kc)" {
                        return "HYPR_T(KC_NO)".into();
                    }
                    return m.replace("(kc)", "(KC_NO)");
                }
            }
        }
        if let Some(name) = self.name_of(code) {
            return name;
        }
        if let Some(lm) = layer_mod_string(code) {
            return lm;
        }
        if modmask != 0 {
            if let Some(key) = self.name_of(keyid) {
                let Some(mask) = mask_name else { return hex(code) };
                if template_prefix(&mask).is_some() {
                    if mask == "ALL_T(kc)" {
                        return format!("HYPR_T({key})");
                    }
                    return mask.replace("(kc)", &format!("({key})"));
                }
                if keyid == 0 {
                    return mask;
                }
                return hex(code);
            }
        }
        hex(code)
    }

    /// The keycode for a name as [`stringify`](Self::stringify) writes it, any
    /// alias, a QK_USER name, or a `0x` number. `None` for an unknown name.
    pub fn parse(&self, name: &str) -> Option<u16> {
        let name = name.trim();
        if name.is_empty() {
            return None;
        }
        if let Some(code) = self.code_of(name) {
            return Some(code);
        }
        if let Some(code) = parse_layer_mod(name) {
            return Some(code);
        }
        if let Some(inner) = name.strip_suffix(')') {
            if let Some((func, arg)) = inner.split_once('(') {
                if is_word(func) && is_word(arg) {
                    if let Some(mask) = self.code_of(&format!("{func}(kc)")) {
                        let arg = if arg == "kc" { "KC_NO" } else { arg };
                        if let Some(key) = self.code_of(arg) {
                            return Some(mask.wrapping_add(key));
                        }
                    }
                }
            }
        }
        if let Some(n) = qk_user_index(name) {
            return Some(QK_USER + n as u16);
        }
        if let Some(h) = name.strip_prefix("0x").or_else(|| name.strip_prefix("0X")) {
            return u16::from_str_radix(h, 16).ok();
        }
        if name.chars().all(|c| c.is_ascii_digit()) {
            return name.parse().ok();
        }
        None
    }

    /// Whether a code has a name (rather than being written as a number).
    pub fn has_name(&self, code: u16) -> bool {
        !self.stringify(code).starts_with("0x")
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn names() -> KeycodeNames {
        KeycodeNames::new(vec![
            CustomKeycode { name: "SV_LEFT_DPI_INC".into(), title: "Left DPI up".into(), short_name: "LDPI+".into() },
            CustomKeycode { name: "SV_SNIPER_2".into(), ..Default::default() },
        ])
    }

    #[test]
    fn stringify_basics() {
        let n = names();
        assert_eq!(n.stringify(0x0000), "KC_NO");
        assert_eq!(n.stringify(0x0001), "KC_TRNS");
        assert_eq!(n.stringify(0x0004), "KC_A");
        assert_eq!(n.stringify(0x0104), "LCTL(KC_A)");
        assert_eq!(n.stringify(0x0100), "LCTL(KC_NO)");
        assert_eq!(n.stringify(0x2204), "LSFT_T(KC_A)");
        assert_eq!(n.stringify(0x2F04), "HYPR_T(KC_A)");
        assert_eq!(n.stringify(0x412C), format!("LT1({})", n.stringify(0x2C)));
        assert_eq!(n.stringify(0x5221), "MO(1)");
        assert_eq!(n.stringify(0x7E40), "SV_LEFT_DPI_INC");
        assert_eq!(n.stringify(0x7E41), "SV_SNIPER_2");
        assert_eq!(n.stringify(0x5022), "LM(1, MOD_LSFT)");
        assert_eq!(n.stringify(0x5033), "LM(1, MOD_RCTL|MOD_RSFT)");
    }

    #[test]
    fn roundtrip_all_codes() {
        let n = names();
        for code in 0..=0xFFFFu16 {
            let s = n.stringify(code);
            assert_eq!(n.parse(&s), Some(code), "code 0x{code:04x} -> {s}");
        }
    }

    #[test]
    fn parse_aliases() {
        let n = names();
        assert_eq!(n.parse("KC_TRANSPARENT"), Some(1));
        assert_eq!(n.parse("_______"), Some(1));
        assert_eq!(n.parse("XXXXXXX"), Some(0));
        assert_eq!(n.parse("LCTL(kc)"), Some(0x0100));
        assert_eq!(n.parse("QK_USER_3"), Some(0x7E43));
        assert_eq!(n.parse("0x7e45"), Some(0x7E45));
        assert_eq!(n.parse("NOT_A_KEY"), None);
        assert_eq!(n.parse("LSFT(KC_A)"), Some(0x0204));
    }
}
